"""실행기 화면 선 아이콘 — 웹(frontend/src/components/icons.jsx)과 같은 Lucide 아이콘(ISC License,
Copyright (c) Lucide Contributors)을 크기 · 색별 PNG 로 담는다.

단일 exe 로 배포하므로 파일을 따로 두지 않는다. Tk 캔버스로 선을 그리면 Windows 에서 계단이 지므로
매끄럽게 줄인 그림을 쓴다. 화면 배율에 맞는 크기를 고른다(늘리지 않는다).
다시 만들 때: Lucide SVG(stroke 2, 둥근 끝) → ImageMagick -density 1200 -resize N -strip → base64.
"""
from __future__ import annotations

import tkinter as tk

SIZES = (18, 23, 27, 36)
TONES = {"muted": "#6B7280", "ink": "#111827"}
_ICONS = {
    ('eye', 'muted', 18): "",
    ('eye', 'muted', 23): "",
    ('eye', 'muted', 27): "",
    ('eye', 'muted', 36): "",
    ('eye', 'ink', 18): "",
    ('eye', 'ink', 23): "",
    ('eye', 'ink', 27): "",
    ('eye', 'ink', 36): "",
    ('eyeoff', 'muted', 18): "",
    ('eyeoff', 'muted', 23): "",
    ('eyeoff', 'muted', 27): "",
    ('eyeoff', 'muted', 36): "",
    ('eyeoff', 'ink', 18): "",
    ('eyeoff', 'ink', 23): "",
    ('eyeoff', 'ink', 27): "",
    ('eyeoff', 'ink', 36): "",
}


def icon(master, name: str, tone: str, size: float) -> tk.PhotoImage:
    """name: eye · eyeoff, tone: muted · ink. size 에 가장 가까운(넘지 않는 쪽 우선) 크기를 고른다."""
    fit = [s for s in SIZES if s <= round(size)]
    px = fit[-1] if fit else SIZES[0]
    return tk.PhotoImage(master=master, data=_ICONS[(name, tone, px)])
